### Modest Suggested Fix
In `packages/better-auth/src/db/internal-adapter.ts:704-748`, track tokens missing from `secondaryStorage` and execute a batch query against the database adapter when `databaseSessionFallbackEnabled` is true:

```typescript
findSessions: async (
    sessionTokens: string[],
    options?: { onlyActiveSessions?: boolean | undefined } | undefined,
) => {
    if (secondaryStorage) {
        const sessions: { session: Session; user: User }[] = [];
        const foundTokens = new Set<string>();

        for (const sessionToken of sessionTokens) {
            const sessionStringified = await secondaryStorage.get(sessionToken);
            if (sessionStringified) {
                try {
                    // ... parse secondaryStorage session ...
                    sessions.push(session);
                    foundTokens.add(sessionToken);
                } catch {
                    continue;
                }
            }
        }

        // If all tokens were resolved from secondary storage, or fallback is disabled, return immediately
        if (!databaseSessionFallbackEnabled || foundTokens.size === sessionTokens.length) {
            return sessions;
        }

        // Fall back to database for missing tokens
        const missingTokens = sessionTokens.filter((token) => !foundTokens.has(token));
        if (missingTokens.length > 0) {
            const currentAdapter = await getCurrentAdapter(adapter);
            const whereClause: Where[] = [
                {
                    field: "token",
                    operator: "in",
                    value: missingTokens,
                },
            ];
            if (options?.onlyActiveSessions) {
                whereClause.push({
                    field: "expiresAt",
                    operator: "gt",
                    value: new Date(),
                });
            }

            const dbSessions = await currentAdapter.findMany<Session & { user: User | null }>({
                model: "session",
                where: whereClause,
                join: {
                    user: true,
                },
            });

            for (const item of dbSessions) {
                const { user, ...session } = item;
                if (!user) continue;
                sessions.push({
                    session: parseSessionOutput(ctx.options, session),
                    user: parseUserOutput(ctx.options, user),
                });
            }
        }

        return sessions;
    }

    // Existing fallback when secondaryStorage is not defined ...
}
```

