```typescript
it.only("should correctly filter fields based on configuration", async () => {
	const loggerErrors: string[] = [];
	const mockLogger = {
		log: (level: string, message: string) => {
			if (level === "error") {
				loggerErrors.push(message);
			}
		},
	};

	const { auth } = await getTestInstance({
		secret: "better-auth.secret",
		user: {
			additionalFields: {
				returned: {
					type: "string",
					defaultValue: "",
					returned: true,
				},
				filtered: {
					type: "string",
					defaultValue: "",
					returned: false,
				},
			},
		},
		session: {
			cookieCache: {
				enabled: true,
			},
		},
		logger: mockLogger,
	});

	// Create a very large string that will exceed the cookie size limit when combined with session data
	// The limit is 4093 bytes, so we create data that will definitely exceed it
	const largeString = "x".repeat(4000);

	// Sign up with large user data using the server API
	const result = await auth.api.signUpEmail({
		body: {
			name: "Test User",
			email: "large-data-test@example.com",
			password: "password123",
			returned: 'This field should be returned',
			filtered: largeString,
		},
	});

	// Check that logger recorded an error about exceeding size limit
	const sizeError = loggerErrors.find((msg) =>
		msg.includes("Session data exceeds cookie size limit"),
	);
	expect(sizeError).toBeUndefined();

	// The sign up should still succeed
	expect(result).toBeDefined();
	expect(result?.user).toBeDefined();
	console.log('result.user', result?.user);

	// `user.returned` is not returned from signUpEmail here, but that's a separate issue
	// already reported in https://github.com/better-auth/better-auth/issues/5291, and
