```ts
// validate-username.ts

import { RegExpMatcher, englishDataset, englishRecommendedTransformers } from 'obscenity'

const disallowedUserNames = ["sa", "sysadmin", "admin", "administration", "moderator", "mod", "staff", "owner"]
const matcher = new RegExpMatcher({
    ...englishDataset.build(),
    ...englishRecommendedTransformers,
});

export function validateUsername(username: any): boolean {
    if (disallowedUserNames.some(i => i === username.toLowerCase().trim()))
        return false
    if (matcher.hasMatch(username)) return false
    return true
}
