```ts
// email-sender.ts
import nodemailer from 'nodemailer'
import SMTPTransport from 'nodemailer/lib/smtp-transport'

function getTransport() {

    let configOptions: SMTPTransport.Options

    switch (process.env.EMAIL_SENDER) {
        default:
        case "SMTP":
            const host = process.env.EMAIL_SMTP_HOST
            const port = process.env.EMAIL_SMTP_PORT
            const user = process.env.EMAIL_SMTP_USER
            const pass = process.env.EMAIL_SMTP_PWD
            const secure = process.env.EMAIL_SMTP_USETLS

            if (!host || !port) throw new Error("Bad SMTP configuration")

            configOptions = {
                host,
                port: +port,
                secure: secure?.toUpperCase() === "TRUE",
            }
            if (user && pass) {
                configOptions.auth = {
                    user,
                    pass
                }
            }
            console.log(configOptions)
            break

        // case "SENDGRID":
        //     console.error("SendGrid Not Implemented")
        //     break

        // case "RESEND":
        //     console.error("Resend Not Implemented")
        //     break
    }

    return nodemailer.createTransport(configOptions)
}

export async function sendMail({
    sendFrom,
    sendTo,
    subject,
    text,
    html,
}: {
    sendFrom: string;
    sendTo: string;
    subject: string;
    text: string;
    html?: string;
}) {
    const transporter = getTransport()
    try {
        const isVerified = await transporter.verify();
    } catch (error) {
        console.error('Something went wrong when sending email', error);
        return;
    }
    const info = await transporter.sendMail({
        from: sendFrom,
        to: sendTo,
        subject: subject,
        text: text,
        html: html ? html : '',
    });
    return info;
}
